WITH rows AS (SELECT json_extract(value, '$.old') AS old, json_extract(value, '$.engine.value') AS new FROM json_each(readfile('data/research/shampoo-inci/approved-weight-consistency-v1/audit.json'), '$.rows')), bands AS (SELECT 'low' AS band, 0 AS ord UNION ALL SELECT 'moderate', 1 UNION ALL SELECT 'high', 2) SELECT band, ord AS 'order', (SELECT count(*) FROM rows WHERE old = band) AS approved, (SELECT count(*) FROM rows WHERE new = band) AS new, 50 AS denominator FROM bands ORDER BY ord;
